#include <zephyr/kernel.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/rtio/rtio.h>
#include <zephyr/drivers/i2c/rtio.h>

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(i2c_rtio, CONFIG_I2C_LOG_LEVEL);

#if CONFIG_I2C_RTIO_COPY_BUF_SLAB_SIZE > 0
/**
 * @brief Transaction that requires copying to/from a temporary buffer
 *
 * Used when the provided buffer is not DMA-able.
 */
struct i2c_rtio_copy_trans {
	/* The i2c message being transferred */
	struct i2c_msg msg;
	/* The sqe that produced this transaction */
	struct rtio_sqe *sqe;
	/* The buffer for copying */
	uint8_t buf[];
};

K_MEM_SLAB_DEFINE_STATIC(i2c_rtio_copy_slab, CONFIG_I2C_RTIO_COPY_BUF_SLAB_SIZE,
			 CONFIG_I2C_RTIO_COPY_BUF_SLAB_COUNT, 4);

/**
 * @brief Check if a buffer needs to be copied
 *
 * @param iodev The iodev
 * @param buf The buffer
 * @param len The length of the buffer
 * @return true If the buffer needs to be copied
 * @return false Otherwise
 */
static bool i2c_rtio_copy_needed(const struct rtio_iodev *iodev, uint8_t *buf, uint32_t len)
{
	const struct i2c_dt_spec *spec = iodev->data;

	return !i2c_is_buffer_accessible(spec->bus, buf, len);
}

/**
 * @brief Allocate a copy transaction
 *
 * @param iodev The iodev
 * @param len The length of the buffer to allocate
 * @return struct i2c_rtio_copy_trans* The allocated transaction
 * @return NULL if no memory
 */
static struct i2c_rtio_copy_trans *i2c_rtio_copy_alloc(const struct rtio_iodev *iodev,
						      uint32_t len)
{
	struct i2c_rtio_copy_trans *copy;

	if (k_mem_slab_alloc(&i2c_rtio_copy_slab, (void **)&copy, K_NO_WAIT) != 0) {
		return NULL;
	}

	return copy;
}

/**
 * @brief Free a copy transaction
 *
 * @param copy The transaction to free
 */
static void i2c_rtio_copy_free(struct i2c_rtio_copy_trans *copy)
{
	k_mem_slab_free(&i2c_rtio_copy_slab, (void **)&copy);
}
#else
static bool i2c_rtio_copy_needed(const struct rtio_iodev *iodev, uint8_t *buf, uint32_t len)
{
	return false;
}
#endif

/**
 * @brief Callback from the i2c transfer
 *
 * @param error Error code from the transfer, 0 on success
 * @param data User data, the rtio_sqe
 */
static void i2c_rtio_xfer_done(int error, void *data)
{
	struct rtio_sqe *sqe = data;
	const struct rtio_iodev *iodev = sqe->iodev;
	struct i2c_rtio_data *dev_data = iodev->api_data;

#if CONFIG_I2C_RTIO_COPY_BUF_SLAB_SIZE > 0
	if (dev_data->curr_copy != NULL) {
		if (error == 0 && (dev_data->curr_copy->msg.flags & I2C_MSG_READ)) {
			memcpy(dev_data->curr_copy->sqe->rx.buf, dev_data->curr_copy->buf,
			       dev_data->curr_copy->msg.len);
		}
		i2c_rtio_copy_free(dev_data->curr_copy);
		dev_data->curr_copy = NULL;
	}
#endif

	rtio_sqe_ok(sqe, error);
	k_sem_give(&dev_data->txn_sem);
}

static void i2c_iodev_submit(struct rtio_iodev *iodev, struct rtio_sqe *sqe)
{
	const struct i2c_dt_spec *spec = iodev->data;
	struct i2c_rtio_data *data = iodev->api_data;
	uint16_t addr = (uint16_t)sqe->iodev_data;
	int res;
	struct i2c_msg msg = {
		.flags = 0,
	};

	if (k_sem_take(&data->txn_sem, K_NO_WAIT) != 0) {
		rtio_sqe_err(sqe, -EBUSY);
		return;
	}

	switch (sqe->op) {
	case RTIO_OP_RX:
		msg.flags |= I2C_MSG_READ;
		/* Fallthrough */
	case RTIO_OP_TX:
		msg.flags |= I2C_MSG_STOP;

		if (sqe->op == RTIO_OP_TX) {
			msg.buf = sqe->tx.buf;
			msg.len = sqe->tx.buf_len;
		} else {
			msg.buf = sqe->rx.buf;
			msg.len = sqe->rx.buf_len;
		}

#if CONFIG_I2C_RTIO_COPY_BUF_SLAB_SIZE > 0
		if (i2c_rtio_copy_needed(iodev, msg.buf, msg.len)) {
			struct i2c_rtio_copy_trans *copy = i2c_rtio_copy_alloc(iodev, msg.len);

			if (copy == NULL) {
				rtio_sqe_err(sqe, -ENOMEM);
				k_sem_give(&data->txn_sem);
				return;
			}

			if (sqe->op == RTIO_OP_TX) {
				memcpy(copy->buf, msg.buf, msg.len);
			}

			msg.buf = copy->buf;
			copy->msg = msg;
			copy->sqe = sqe;
			data->curr_copy = copy;
		}
#endif

		res = i2c_transfer_cb(spec->bus, &msg, 1, addr, i2c_rtio_xfer_done, sqe);
		if (res != 0) {
			rtio_sqe_err(sqe, res);
			k_sem_give(&data->txn_sem);
		}
		break;
	default:
		rtio_sqe_err(sqe, -ENOTSUP);
		k_sem_give(&data->txn_sem);
	}
}

#if CONFIG_I2C_RTIO_FALLBACK
/**
 * @brief Work handler for fallback synchronous operation
 *
 * @param item The work item
 */
static void i2c_iodev_submit_work_handler(struct k_work *item)
{
	struct rtio_sqe *sqe = CONTAINER_OF(item, struct rtio_sqe, work);
	const struct rtio_iodev *iodev = sqe->iodev;
	const struct i2c_dt_spec *spec = iodev->data;
	int res;

	LOG_DBG("Sync RTIO work item for: %p", sqe);

	switch (sqe->op) {
	case RTIO_OP_RX:
		res = i2c_read_dt(spec, sqe->rx.buf, sqe->rx.buf_len);
		break;
	case RTIO_OP_TX:
		res = i2c_write_dt(spec, sqe->tx.buf, sqe->tx.buf_len);
		break;
	default:
		res = -ENOTSUP;
	}

	rtio_sqe_ok(sqe, res);
}

/**
 * @brief Submit an i2c request using the fallback path
 *
 * @param iodev The iodev
 * @param sqe The submission queue entry
 */
static void i2c_iodev_submit_fallback(struct rtio_iodev *iodev, struct rtio_sqe *sqe)
{
	LOG_DBG("Executing fallback for dev: %p, sqe: %p", iodev->dev, sqe);

	k_work_init(&sqe->work, i2c_iodev_submit_work_handler);
	k_work_submit(&sqe->work);
}
#endif

/**
 * @brief Setup the iodev for the i2c device
 *
 * @param iodev The iodev
 * @param dev The i2c device
 * @return int 0 on success
 */
static int i2c_rtio_iodev_setup(const struct rtio_iodev *iodev, const struct device *dev)
{
	const struct i2c_driver_api *api = (const struct i2c_driver_api *)dev->api;
	struct i2c_rtio_data *data = iodev->api_data;

	k_sem_init(&data->txn_sem, 1, 1);

	if (api->transfer_cb != NULL) {
		((struct rtio_iodev_api *)iodev->api)->submit = i2c_iodev_submit;
	}
#if CONFIG_I2C_RTIO_FALLBACK
	else {
		((struct rtio_iodev_api *)iodev->api)->submit = i2c_iodev_submit_fallback;
	}
#endif

	return 0;
}

const struct rtio_iodev_api i2c_rtio_iodev_api = {
	.setup = i2c_rtio_iodev_setup,
	.submit = NULL, /* Set in setup */
};
